// Custom Cloudflare Worker entry: the OpenNext-built Next.js app plus cron
// triggers (replacing the old Netlify scheduled functions).
// @ts-ignore — generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js';

type Env = { CRON_SECRET?: string } & Record<string, unknown>;

// Must match the "triggers.crons" list in wrangler.jsonc.
const CRON_JOBS: Record<string, string> = {
  '0 2 * * *': 'milestones',
  '0 3 * * SUN': 'cleanup',
  '15 0 1 1 *': 'rollover',
};

export default {
  fetch: handler.fetch,

  async scheduled(controller: ScheduledController, env: Env, ctx: ExecutionContext) {
    const job = CRON_JOBS[controller.cron];
    if (!job) {
      console.error(`No job mapped to cron "${controller.cron}"`);
      return;
    }
    const request = new Request(`https://internal/api/cron/${job}`, {
      method: 'POST',
      headers: { 'x-cron-secret': env.CRON_SECRET ?? '' },
    });
    const response: Response = await handler.fetch(request, env, ctx);
    const body = await response.text();
    if (!response.ok) throw new Error(`Cron job ${job} failed (${response.status}): ${body}`);
    console.log(`Cron job ${job}: ${body}`);
  },
} satisfies ExportedHandler<Env>;

// Re-export Durable Objects used by OpenNext (harmless if unused).
// @ts-ignore
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js';
